140	/* 校验并解析一帧数据区（d 指向 type 字节，len = 数据区长度）
141	 * 成功更新 g_ld2410b_state / g_ld2410b_dist_cm 并返回 0 */
142	static int ld2410b_parse_frame(const uint8_t *d, int len)
143	{
144	  if (len < DATA_LEN_BASIC)
145	    return -1;
146	  if (d[0] != DATA_TYPE_BASIC || d[1] != DATA_HEAD_AA)
147	    return -1;                       /* 非目标基本信息帧 */
148	  if (d[OFF_STATE] > 0x03)
149	    return -1;                       /* 状态值非法（底噪检测等不理会） */
150	  if (d[11] != DATA_TAIL_55 || d[12] != 0x00)
151	    return -1;                       /* 数据区尾部校验失败 */
152	
153	  g_ld2410b_state   = d[OFF_STATE];
154	  g_ld2410b_dist_cm = ld2410b_le16(&d[OFF_DET_DIST]);
155	  g_ld2410b_frame_ok = true;
156	  g_ld2410b_last_ts = lv_tick_get();   /* WARN3：记录帧到达时刻供过期判断 */
157	  g_ld2410b_frame_cnt++;               /* 调试：有效帧计数 */
158	
159	  /* 2026-08-26 调试日志：状态变化才打印（有人↔无人切换），防每帧刷屏 */
160	  if (g_ld2410b_state != g_ld2410b_log_state)
161	    {
162	      g_ld2410b_log_state = g_ld2410b_state;
163	      LV_LOG_USER("[ld2410b] state=%d dist=%dcm", g_ld2410b_state,
164	                  g_ld2410b_dist_cm);
165	    }
166	  return 0;
167	}
