169	/* 发送一条配置命令帧（协议 V1.08 §2.1.2，小端）：
170	 *   FD FC FB FA | len(2B)=2+vlen | cmd(2B) | value(vlen) | 04 03 02 01
171	 * best-effort：模块未接/波特率不符时静默失败，不影响主流程。 */
172	static void ld2410b_send_cmd(int fd, uint16_t cmd, const uint8_t *val, int vlen)
173	{
174	  uint8_t buf[32];
175	  int n = 0;
176	  int i;
177	
178	  buf[n++] = CMD_HDR0;
179	  buf[n++] = CMD_HDR1;
180	  buf[n++] = CMD_HDR2;
181	  buf[n++] = CMD_HDR3;
182	  buf[n++] = (uint8_t)((2 + vlen) & 0xff);
183	  buf[n++] = (uint8_t)((2 + vlen) >> 8);
184	  buf[n++] = (uint8_t)(cmd & 0xff);
185	  buf[n++] = (uint8_t)(cmd >> 8);
186	  for (i = 0; i < vlen; i++)
187	    buf[n++] = val[i];
188	  buf[n++] = CMD_TAIL0;
189	  buf[n++] = CMD_TAIL1;
190	  buf[n++] = CMD_TAIL2;
191	  buf[n++] = CMD_TAIL3;
192	
193	  (void)write(fd, buf, n);
194	}
