196	/* 初始化下发模块配置：最大距离门 + 无人延时（命令 0x0060，协议 V1.08 §2.2.3）。
197	 * 流程：使能配置 → 0x0060 → 结束配置（协议 §2.4.1）。
198	 * 无人延时即时生效；最大距离门掉电不丢失。 */
199	static void ld2410b_apply_config(int fd)
200	{
201	  uint8_t enable[2] = { 0x01, 0x00 };   /* 使能配置命令值 0x0001 */
202	  uint8_t val[18];
203	  int i = 0;
204	
205	  /* 0x0060 命令值：2B 最大运动距离门字(0x0000)+4B 参数
206	   *               +2B 最大静止距离门字(0x0001)+4B 参数
207	   *               +2B 无人持续时间字(0x0002)+4B 参数 */
208	  val[i++] = 0x00; val[i++] = 0x00;                    /* 最大运动距离门字 */
209	  val[i++] = (uint8_t)(LD2410B_CFG_MAX_GATE & 0xff);
210	  val[i++] = (uint8_t)(LD2410B_CFG_MAX_GATE >> 8);
211	  val[i++] = 0x00; val[i++] = 0x00;
212	  val[i++] = 0x01; val[i++] = 0x00;                    /* 最大静止距离门字 */
213	  val[i++] = (uint8_t)(LD2410B_CFG_MAX_GATE & 0xff);
214	  val[i++] = (uint8_t)(LD2410B_CFG_MAX_GATE >> 8);
215	  val[i++] = 0x00; val[i++] = 0x00;
216	  val[i++] = 0x02; val[i++] = 0x00;                    /* 无人持续时间字 */
217	  val[i++] = (uint8_t)(LD2410B_CFG_NODELAY_S & 0xff);
218	  val[i++] = (uint8_t)(LD2410B_CFG_NODELAY_S >> 8);
219	  val[i++] = 0x00; val[i++] = 0x00;
220	
221	  ld2410b_send_cmd(fd, CMD_ENABLE_CFG, enable, 2);
222	  usleep(20 * 1000);
223	  ld2410b_send_cmd(fd, CMD_SET_GATE_NODELAY, val, 18);
224	  usleep(20 * 1000);
225	  ld2410b_send_cmd(fd, CMD_DISABLE_CFG, NULL, 0);
226	  usleep(20 * 1000);
227	
228	  /* 2026-08-26 调试日志：配置下发结果（best-effort，模块未接/波特率不符时不回 ACK） */
229	  LV_LOG_USER("[ld2410b] cfg sent: maxgate=%d nodelay=%ds", LD2410B_CFG_MAX_GATE,
230	              LD2410B_CFG_NODELAY_S);
231	}
