343	int dm_ld2410b_init(void)
344	{
345	  struct termios tio;
346	  int fd;
347	
348	  if (g_ld2410b_ready)
349	    return 0;                        /* 已初始化 */
350	
351	  fd = open(LD2410B_DEV, O_RDWR | O_NONBLOCK);
352	  if (fd < 0)
353	    {
354	      LV_LOG_ERROR("[ld2410b] open %s failed: %d", LD2410B_DEV, errno);
355	      return -1;
356	    }
357	
358	  /* 115200 8N1，raw 模式 */
359	  memset(&tio, 0, sizeof(tio));
360	  if (tcgetattr(fd, &tio) < 0)
361	    {
362	      close(fd);
363	      return -1;
364	    }
365	  cfmakeraw(&tio);
366	  cfsetispeed(&tio, LD2410B_BAUD);
367	  cfsetospeed(&tio, LD2410B_BAUD);
368	  tio.c_cflag |= (CLOCAL | CREAD);
369	  if (tcsetattr(fd, TCSANOW, &tio) < 0)
370	    {
371	      close(fd);
372	      return -1;
373	    }
374	
375	  /* 2026-08-26：初始化下发模块配置（最大距离门 + 无人延时，命令 0x0060）。
376	   * best-effort：模块未接/波特率仍为 256000 时静默失败，不影响主流程。 */
377	  ld2410b_apply_config(fd);
378	
379	  g_ld2410b_run = true;
380	  if (pthread_create(&g_ld2410b_thread, NULL, ld2410b_reader,
381	                     (void *)(intptr_t)fd) != 0)
382	    {
383	      close(fd);
384	      g_ld2410b_run = false;
385	      return -1;
386	    }
387	
388	  g_ld2410b_ready = true;
389	  LV_LOG_USER("[ld2410b] init ok (%s @115200)", LD2410B_DEV);
390	  return 0;
391	}
