644	 * dm_health.c 调用：人体感应距离 cm
645	 * 2026-08-23：数据源从 LTR553 接近传感器切换为 LD2410B 毫米波雷达。
646	 *   - 有人（状态≠NONE）且 探测距离 ≤ 在座阈值 → 返回 0（在座）
647	 *   - 有人但超出阈值 / 无人 → 返回 99（离开）
648	 *   - LD2410B 串口不可用 → -1（dm_health 回退纯计时模式）
649	 * 2026-08-27：阈值从写死 200 改为读 dm_health_cfg 的 ld2410_seat_cm
650	 *   （默认 150 = 1.5m/2 门，用户拍板；原 prox_seat_cm=30 死配置已删） */
651	int dm_prox_get_cm(void)
652	{
653	    int present = dm_ld2410b_present();
654	    int seat_cm = dm_health_cfg_get_int("ld2410_seat_cm",
655	                                        LD2410B_SEAT_CM_DEFAULT);
656	    int dist;
657	
658	    if (present < 0)
659	        return -1;       /* 串口未就绪：回退纯计时 */
660	    if (present == 0)
661	        return 99;       /* 无人：离开 */
662	
663	    dist = dm_ld2410b_get_dist_cm();
664	    if (dist >= 0 && dist <= seat_cm)
665	        return 0;        /* 有人且在座距离内：在座 */
666	    return 99;           /* 有人但超出阈值 / 距离未知：离开 */
667	}
