    if (standby_prox_lbl)
    {
        int p = dm_ld2410b_present();
        static int dbg_p = -2, dbg_dist = -2;
        int dbg_d = dm_ld2410b_get_dist_cm();
        if (p != dbg_p || dbg_d != dbg_dist)
        {
            dbg_p = p;
            dbg_dist = dbg_d;
            LV_LOG_USER("[prox] standby p=%d dist=%d", p, dbg_d);
        }
        if (p < 0)
            lv_label_set_text(standby_prox_lbl, "人体：不可用");
        else if (p == 0)
            lv_label_set_text(standby_prox_lbl, "人体：无人");
        else
        {
            /* 有人：附带探测距离（0.75m 距离门分辨率，显示到 0.1m；
